import Foundation

extension Bundle {
	/// TobyCore's SwiftPM resource bundle (`TobyApp_TobyCore.bundle`).
	///
	/// The `Bundle.module` accessor generated by SwiftPM's native build system
	/// only checks the `.app` root and the absolute build directory, so a
	/// packaged app (bundle in `Contents/Resources/`) traps on any Mac without
	/// that build tree. Look in the main bundle's resources first; fall back to
	/// `Bundle.module` for tests and command-line tools.
	static let tobyCoreResources: Bundle = {
		if let url = Bundle.main.url(forResource: "TobyApp_TobyCore", withExtension: "bundle"),
		   let bundle = Bundle(url: url)
		{
			return bundle
		}
		return .module
	}()
}
